SELECT l.id, l.macro_id, l.fusionauth_user_id, l.email_address, l.provider as "provider: _", l.is_sync_active, l.is_primary, l.needs_reauth, l.last_sync_error_at, l.created_at, l.updated_at FROM email_messages m JOIN email_links l ON l.id = m.link_id WHERE m.id = $1 AND ( l.macro_id = $2 OR EXISTS ( SELECT 1 FROM macro_user_links mul WHERE mul.link_id = l.id AND mul.primary_macro_id = $2 ) )
